def transform(grid):
    import collections
    g = np.array(grid)
    H, W = g.shape
    bg = background(g)
    objs = objects(g, bg=bg, multicolour=True)
    markers = []  # (colour, axis, pos, edge)
    shapes = []
    for o in objs:
        if o["size"] == 1:
            y, x = o["cells"][0]
            c = int(g[y, x])
            on_lr = x == 0 or x == W - 1
            on_tb = y == 0 or y == H - 1
            if on_lr and not on_tb:
                markers.append((c, "row", y, x))
            elif on_tb and not on_lr:
                markers.append((c, "col", x, y))
            else:
                shapes.append(o)
        else:
            shapes.append(o)
    mcol = {}
    for c, ax, p, e in markers:
        mcol.setdefault(c, (ax, p, e))
    out = g.copy()
    moves = []
    for o in shapes:
        cols = collections.Counter(int(g[y, x]) for y, x in o["cells"])
        cand = [c for c in cols if c in mcol]
        if not cand:
            continue
        key = min(cand, key=lambda c: cols[c])
        ky, kx = next((y, x) for y, x in o["cells"] if g[y, x] == key)
        ax, p, e = mcol[key]
        if ax == "row":
            dy, dx = p - ky, 0
        else:
            dy, dx = 0, p - kx
        moves.append((o, dy, dx))
    for o, dy, dx in moves:
        for y, x in o["cells"]:
            out[y, x] = bg
    if moves:
        emit(out.copy(), "Erase every shape that contains a key colour matching an edge marker.")
    for i, (o, dy, dx) in enumerate(moves):
        for y, x in o["cells"]:
            ny, nx = y + dy, x + dx
            if 0 <= ny < H and 0 <= nx < W:
                out[ny, nx] = g[y, x]
        if i < len(moves) - 1:
            emit(out.copy(), f"Redraw a shape shifted by ({dy},{dx}) so its key cell lines up with the matching edge marker.")
    emit(out.copy(), "All shapes aligned with their markers.")
    return out
